package com.bplus.share;
import android.app.*;import android.content.*;import android.os.Bundle;import android.widget.*;import android.view.Gravity;import android.text.InputType;
public class ProfileActivity extends Activity {
 private EditText name,email,phone;private CheckBox shareEmail,sharePhone;private boolean draftShareEmail,draftSharePhone;private String draftName,draftEmail,draftPhone;
 @Override protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);Profile.init();draftName=b==null?Store.get("profileName",Store.deviceName()):b.getString("name","");draftEmail=b==null?Store.get("profileEmail",""):b.getString("email","");draftPhone=b==null?Store.get("profilePhone",""):b.getString("phone","");draftShareEmail=b==null?Store.get("shareProfileEmail","0").equals("1"):b.getBoolean("shareEmail");draftSharePhone=b==null?Store.get("shareProfilePhone","0").equals("1"):b.getBoolean("sharePhone");build();}
 private EditText field(String value,int type,int max){EditText e=new EditText(this);e.setText(value);e.setTextColor(Ui.text);e.setSingleLine(true);e.setInputType(type);e.setTypeface(App.cairo);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(max)});return e;}
 private void remember(){if(name!=null){draftName=name.getText().toString();draftEmail=email.getText().toString();draftPhone=phone.getText().toString();draftShareEmail=shareEmail.isChecked();draftSharePhone=sharePhone.isChecked();}}
 protected void onSaveInstanceState(Bundle b){remember();b.putString("name",draftName);b.putString("email",draftEmail);b.putString("phone",draftPhone);b.putBoolean("shareEmail",draftShareEmail);b.putBoolean("sharePhone",draftSharePhone);super.onSaveInstanceState(b);}
 private void build(){LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.my_profile),true,null));ScrollView scroll=new ScrollView(this);LinearLayout box=Ui.col(this);Ui.pad(box,24,18,24,24,this);scroll.addView(box);root.addView(scroll,Ui.lpW1());LinearLayout hero=Ui.col(this);hero.setGravity(Gravity.CENTER_HORIZONTAL);hero.addView(Profile.avatar(this,Profile.local(),144));TextView photo=Ui.ghost(this,getString(R.string.change_photo));LinearLayout.LayoutParams pp=Ui.lp(-2,-2);pp.topMargin=Ui.dp(this,12);hero.addView(photo,pp);box.addView(hero,Ui.lp(-1,-2));photo.setOnClickListener(v->{remember();Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivityForResult(i,83);});box.addView(Ui.secHead(this,getString(R.string.display_name)));name=field(draftName,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS,80);box.addView(name);box.addView(Ui.secHead(this,getString(R.string.profile_email)));email=field(draftEmail,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS,254);email.setTextDirection(android.view.View.TEXT_DIRECTION_LTR);box.addView(email);shareEmail=new CheckBox(this);shareEmail.setText(R.string.profile_share_field);shareEmail.setTextColor(Ui.dim);shareEmail.setTypeface(App.cairo);shareEmail.setChecked(draftShareEmail);box.addView(shareEmail);box.addView(Ui.secHead(this,getString(R.string.profile_phone)));phone=field(draftPhone,InputType.TYPE_CLASS_PHONE,40);phone.setTextDirection(android.view.View.TEXT_DIRECTION_LTR);box.addView(phone);sharePhone=new CheckBox(this);sharePhone.setText(R.string.profile_share_field);sharePhone.setTextColor(Ui.dim);sharePhone.setTypeface(App.cairo);sharePhone.setChecked(draftSharePhone);box.addView(sharePhone);box.addView(Ui.t(this,getString(R.string.profile_contact_paired),12,Ui.dim,App.cairoSB));box.addView(Ui.secHead(this,getString(R.string.username_label)));TextView handle=Ui.t(this,"@"+Store.get("username",""),22,Ui.accent,App.cairoB);box.addView(handle);handle.setOnClickListener(v->PairUi.copy(this,handle.getText().toString()));box.addView(Ui.t(this,getString(R.string.profile_privacy),13,Ui.dim,App.cairoSB));TextView save=Ui.cta(this,getString(R.string.save_profile));box.addView(save);save.setOnClickListener(v->{remember();String n=draftName.trim(),e=draftEmail.trim(),p=draftPhone.trim();if(n.isEmpty()){name.setError(getString(R.string.profile_name_required));return;}if(!e.isEmpty()&&!android.util.Patterns.EMAIL_ADDRESS.matcher(e).matches()){email.setError(getString(R.string.profile_email_invalid));return;}try{Store.saveLocalProfile(n,e,p,draftShareEmail,draftSharePhone);Outbox.kick();Toast.makeText(this,getString(R.string.profile_saved),0).show();startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}catch(Exception ex){new AppDialog(this).setMessage(R.string.profile_save_failed).setPositiveButton(android.R.string.ok,null).show();}});setContentView(root);}
 @Override protected void onActivityResult(int q,int r,Intent data){super.onActivityResult(q,r,data);if(q==84){build();return;}if(q==83&&r==RESULT_OK&&data!=null&&data.getData()!=null){try{Intent crop=new Intent(this,CropActivity.class);crop.putExtra("uri",data.getData().toString());crop.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(crop,84);}catch(Exception e){new AppDialog(this).setMessage(e.getMessage()).setPositiveButton(android.R.string.ok,null).show();}}}
}
